mapper.delete:
DELETE FROM MEMBER_CONTENT
 WHERE MEMBER_ID = #{memberId}
   AND CONTENT_ID = #{contentId}

mapper.select:
SELECT MEMBER_ID, CONTENT_ID, RATING_SCORE, WATCHLIST, RATED_DT, WATCHLIST_DT, UPDATED_DT FROM ( SELECT MC.MEMBER_ID, MC.CONTENT_ID, MC.RATING_SCORE, MC.WATCHLIST, TO_CHAR(MC.RATED_DT, 'YYYY-MM-DD HH24:MI:SS') AS RATED_DT, TO_CHAR(MC.WATCHLIST_DT, 'YYYY-MM-DD HH24:MI:SS') AS WATCHLIST_DT, TO_CHAR(MC.UPDATED_DT, 'YYYY-MM-DD HH24:MI:SS') AS UPDATED_DT, ROW_NUMBER() OVER ( ORDER BY MC.UPDATED_DT DESC, MC.MEMBER_ID DESC, MC.CONTENT_ID DESC ) AS RNUM FROM MEMBER_CONTENT MC
AND MC.MEMBER_ID = #{searchWord}
AND MC.CONTENT_ID = #{searchWord}
AND MC.WATCHLIST = #{searchWord}
AND MC.RATING_SCORE = #{searchWord}
)
WHERE RNUM BETWEEN ((#{pageNo} - 1) * #{pageSize} + 1) AND (#{pageNo} * #{pageSize})
ORDER BY RNUM
